      const text = (title + ' ' + desc).toLowerCase();
      const tnKeywords = [
        'tây ninh', 'tay ninh', 'núi bà đen', 'nui ba den', 'bà đen', 'ba den',
        'toà thánh', 'tòa thánh', 'toa thanh', 'cao đài', 'cao dai',
