        'long an', 'bình dương', 'đồng nai', 'tiền giang', 'bến tre',
        'vĩnh long', 'cần thơ', 'hà nội', 'đà nẵng', 'bình thuận',
        'khánh hòa', 'bình phước'
      ];
      const hasOther = otherProvinces.some(p => text.includes(p));
      if (hasOther && !text.includes('tây ninh') && !text.includes('tay ninh')) {
        return false;
      }
      return true;
    };

    const detectTayNinhLocation = (title) => {
      const t = title.toLowerCase();
      if (t.includes('núi bà đen') || t.includes('ma thiên lãnh')) return 'TP. Tây Ninh';
      if (t.includes('tòa thánh') || t.includes('hòa thành')) return 'TX. Hòa Thành';
      if (t.includes('trảng bàng')) return 'TX. Trảng Bàng';
      if (t.includes('dầu tiếng') || t.includes('dương minh châu')) return 'H. Dương Minh Châu';
      if (t.includes('tân biên') || t.includes('trung ương cục') || t.includes('lò gò')) return 'Huyện Tân Biên';
      if (t.includes('tân châu')) return 'Huyện Tân Châu';
      if (t.includes('gò dầu')) return 'Huyện Gò Dầu';
      if (t.includes('bến cầu') || t.includes('mộc bài')) return 'Huyện Bến Cầu';
      if (t.includes('châu thành') || t.includes('tua hai')) return 'Huyện Châu Thành';
      return 'Tỉnh Tây Ninh';
    };

    const detectTayNinhCategory = (title) => {
      const t = title.toLowerCase();
      if (t.includes('núi bà đen') || t.includes('cáp treo') || t.includes('du lịch')) return 'Du lịch & Khám phá';
      if (t.includes('tòa thánh') || t.includes('cao đài') || t.includes('chùa')) return 'Văn hóa & Tâm linh';
      if (t.includes('ẩm thực') || t.includes('bánh tráng') || t.includes('bò tơ') || t.includes('muối tôm')) return 'Ẩm thực đặc sản';
      if (t.includes('lịch sử') || t.includes('di tích') || t.includes('trung ương cục') || t.includes('tua hai')) return 'Lịch sử & Nguồn cội';
      return 'Thời sự Tây Ninh';
    };

    const fetchTayNinhVideos = async () => {
      isFetchingVideos.value = true;
      showToast('Đang cập nhật video YouTube nói về tỉnh Tây Ninh...', 'info');

      // 2 kênh YouTube chính thức của Đài PT-TH Tây Ninh (TTV11 / Báo Tây Ninh)
      const channels = [
        { id: 'UCLXwTlUcQi4LGH5sq_fyMAg', name: 'Đài PT-TH Tây Ninh (TTV11)' },
        { id: 'UCjSFBpBDZB8-XWcwXIH20FQ', name: 'Truyền Hình Tây Ninh Official' }
      ];

      let addedCount = 0;
      for (const ch of channels) {
        try {
          const feedUrl = 'https://www.youtube.com/feeds/videos.xml?channel_id=' + ch.id;
          const proxyUrl = 'https://api.rss2json.com/v1/api.json?rss_url=' + encodeURIComponent(feedUrl);
          const res = await fetch(proxyUrl);
          const data = await res.json();
          if (data && data.status === 'ok' && Array.isArray(data.items)) {
            data.items.forEach(item => {
              const title = item.title || '';
              const desc = item.description || '';
              const link = item.link || '';

              // Chỉ lấy video thực sự nói về tỉnh Tây Ninh
              if (isTayNinhOnly(title, desc)) {
                const match = link.match(/(?:v=|shorts\/|embed\/)([\w-]{11})/);
                const yId = match ? match[1] : '';
                if (yId && !tayNinhVideos.value.some(v => v.youtubeId === yId)) {
                  tayNinhVideos.value.unshift({
                    id: 'yt_' + yId,
                    youtubeId: yId,
                    title: title,
                    channel: ch.name,
                    duration: 'Mới cập nhật',
                    views: 'YouTube',
                    location: detectTayNinhLocation(title),
                    category: detectTayNinhCategory(title),
                    thumbnail: item.thumbnail || ('https://i.ytimg.com/vi/' + yId + '/hqdefault.jpg'),
                    embedUrl: 'https://www.youtube.com/embed/' + yId
                  });
                  addedCount++;
                }
              }
            });
          }
        } catch (err) {
          console.warn('Lỗi tải video kênh ' + ch.name + ':', err);
        }
      }

      isFetchingVideos.value = false;
      if (addedCount > 0) {
        showToast('Đã lấy thêm ' + addedCount + ' video mới về tỉnh Tây Ninh!', 'success');
      } else {
        showToast('Đã lọc và cập nhật toàn bộ video về tỉnh Tây Ninh!', 'success');
      }
    };

    const filteredTayNinhVideos = computed(() => {
      if (!videoCategory.value || videoCategory.value === 'all') {
        return tayNinhVideos.value;
      }
      return tayNinhVideos.value.filter(v => {
        const cat = (v.category || '').toLowerCase();
        const tit = (v.title || '').toLowerCase();
        if (videoCategory.value === 'dulich') {
          return cat.includes('du lịch') || tit.includes('bà đen') || tit.includes('núi') || tit.includes('dầu tiếng');
        }
        if (videoCategory.value === 'vanhoa') {
          return cat.includes('văn hóa') || cat.includes('tâm linh') || tit.includes('tòa thánh') || tit.includes('cao đài');
        }
        if (videoCategory.value === 'amthuc') {
          return cat.includes('ẩm thực') || tit.includes('bánh tráng') || tit.includes('bò tơ') || tit.includes('muối tôm');
        }
        if (videoCategory.value === 'thoisu') {
          return cat.includes('thời sự') || v.channel.includes('TTV11') || v.channel.includes('Tây Ninh');
        }
        return true;
      });
    });

    const activePlayingVideo = ref(null);
