    let notifUnsubscribe = null;

    const toggleNotificationDropdown = () => {
      showNotificationDropdown.value = !showNotificationDropdown.value;
    };

    const markAllNotificationsAsRead = async () => {
      unreadNotificationCount.value = 0;
      notifications.value.forEach(n => { n.read = true; });
      if (db && currentUser.value) {
        try {
          for (const n of notifications.value) {
            if (n.id && !n.id.startsWith('temp_')) {
              await updateDoc(doc(db, 'notifications', n.id), { read: true });
            }
          }
        } catch (e) {
          console.warn('Lỗi markAllNotificationsAsRead:', e);
        }
      }
    };

    const handleNotificationClick = async (notif) => {
      if (!notif) return;
      notif.read = true;
      unreadNotificationCount.value = notifications.value.filter(n => !n.read).length;
      showNotificationDropdown.value = false;

      if (db && notif.id && !notif.id.startsWith('temp_')) {
        try {
          await updateDoc(doc(db, 'notifications', notif.id), { read: true });
        } catch(e) {}
      }

      if (notif.type === 'private_chat') {
        openPrivateChat({
          email: notif.senderEmail,
          name: notif.senderName,
          avatar: notif.senderAvatar
        });
      } else if (notif.type === 'comment' && notif.targetPostId) {
        openDetailModal({ id: notif.targetPostId });
      }
    };

    const clearNotification = async (notifId) => {
      notifications.value = notifications.value.filter(n => n.id !== notifId);
      unreadNotificationCount.value = notifications.value.filter(n => !n.read).length;
      if (db && notifId) {
        try {
          await deleteDoc(doc(db, 'notifications', notifId));
        } catch(e) {}
      }
    };

    const listenRealtimeNotifications = (email) => {
      if (!db || !email) return;
      if (notifUnsubscribe) {
        notifUnsubscribe();
        notifUnsubscribe = null;
      }
      try {
        const cleanEmail = email.toLowerCase().trim();
        const notifsRef = collection(db, 'notifications');
        const q = query(notifsRef, where('receiverEmail', '==', cleanEmail), limit(50));
        let initialNotifsDone = false;
        notifUnsubscribe = onSnapshot(q, (snapshot) => {
          const list = [];
          snapshot.forEach(d => {
            list.push({ id: d.id, ...d.data() });
          });
          list.sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
          notifications.value = list;
          unreadNotificationCount.value = list.filter(n => !n.read).length;

          if (initialNotifsDone) {
            snapshot.docChanges().forEach(change => {
              if (change.type === 'added') {
                const d = change.doc.data();
                playNotificationSound();
                const icon = d.type === 'private_chat' ? '💬 ' : (d.type === 'comment' ? '📝 ' : '🔔 ');
                showToast(icon + (d.title || 'Thông báo mới') + ': ' + (d.content ? d.content.substring(0, 50) : ''), 'info', d.senderName || 'TNHub Tây Ninh');
              }
            });
          }
          initialNotifsDone = true;
        }, (err) => {
          console.warn('Notifications snapshot warning:', err);
        });
      } catch (e) {
        console.warn('Setup notifications warning:', e);
      }
    };

    const playNotificationSound = () => {
      try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (!AudioContext) return;
        const ctx = new AudioContext();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(587.33, ctx.currentTime);
        osc.frequency.setValueAtTime(880, ctx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.15, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.35);
        osc.start();
        osc.stop(ctx.currentTime + 0.35);
      } catch (e) {}
    };

    const formatTime = (isoString) => {
      if (!isoString) return 'Vừa xong';
      try {
        const diff = Math.floor((Date.now() - new Date(isoString).getTime()) / 1000);
        if (diff < 60) return 'Vừa xong';
        if (diff < 3600) return Math.floor(diff / 60) + ' phút trước';
        if (diff < 86400) return Math.floor(diff / 3600) + ' giờ trước';
        return Math.floor(diff / 86400) + ' ngày trước';
      } catch (e) {
        return 'Gần đây';
      }
    };

    const sendCommunityMessage = async () => {
      if (!currentUser.value || !currentUser.value.uid) {
        showToast('Vui lòng đăng nhập Google để gửi tin nhắn cộng đồng.', 'warning');
        loginGoogle();
        return;
      }
      const text = chatMessageInput.value.trim();
      if (!text) return;

      const newMsg = {
        senderName: currentUser.value ? (currentUser.value.displayName || 'Thành viên Google') : 'Thành viên Tây Ninh',
        senderEmail: currentUser.value ? currentUser.value.email : 'ptquang0968@gmail.com',
        text: text,
        createdAt: new Date().toISOString()
      };

      communityMessages.value.unshift({ id: 'msg_' + Date.now(), ...newMsg });

      if (db) {
        try {
          addDoc(collection(db, 'messages'), newMsg).catch(err => console.warn('Sync message:', err));
        } catch (e) {
          console.warn('Error sending message:', e);
        }
      }

      chatMessageInput.value = '';
      showToast('Đã gửi tin nhắn lên cộng đồng Tây Ninh!', 'success');
    };

    const selectPin = (target) => {
      let found = null;
      if (target && typeof target === 'object') {
        found = cards.value.find(c => c.id === target.id) || target;
      } else if (typeof target === 'number') {
        const idx = target - 1;
        if (idx >= 0 && idx < cards.value.length) {
          found = cards.value[idx];
        }
      } else if (typeof target === 'string') {
        found = cards.value.find(c => c.id === target);
      }

      if (found) {
        const loc = found.location || 'TP. Tây Ninh';
        selectedPinItem.value = {
          id: found.id,
          title: found.title,
          price: found.price,
          location: loc,
          image: found.image || 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=120&h=120&q=80'
        };
        const queryLocation = encodeURIComponent(loc + ', Tây Ninh, Việt Nam');
        mapEmbedUrl.value = 'https://maps.google.com/maps?q=' + queryLocation + '&t=&z=14&ie=UTF8&iwloc=&output=embed';
        showToast('Đang xem vị trí: ' + found.title + ' (' + loc + ')', 'info');
      }
    };

