          setDoc(doc(db, 'listings', newCard.id), newCard)
            .then(() => console.log('Đã lưu bài viết lên Firestore thành công!'))
            .catch(e => console.warn('Sync post to firestore notice:', e));
        } catch (e) {
          console.warn('Firestore setDoc:', e);
        }
