    // ==========================================
    // CÁC HÀM XỬ LÝ PROFILE, BÀI ĐĂNG CỦA TÔI, BẠN BÈ, CHAT PRIVATE
    // ==========================================
    const myPostsCount = computed(() => {
      if (!currentUser.value) return 0;
      const myEmail = currentUser.value.email || '';
      const myUid = currentUser.value.uid || '';
      return cards.value.filter(c => (myEmail && c.authorEmail === myEmail) || (myUid && c.userId === myUid)).length;
    });

    const isMyPost = (card) => {
      if (!currentUser.value || !card) return false;
      return (card.authorEmail && card.authorEmail === currentUser.value.email) || 
             (card.userId && card.userId === currentUser.value.uid);
    };

    const confirmDeleteMyPost = (card) => {
      showPopup({
        title: 'Xóa bài viết của bạn',
        message: 'Bạn có chắc chắn muốn xóa bài viết "' + (card.title || '') + '"? Thao tác này không thể hoàn tác.',
        type: 'confirm',
