    // ==========================================
    // CÁC HÀM XỬ LÝ ADMIN CRAWLER
    // ==========================================
    const openCrawlerModal = () => {
      if (!isAdmin.value) {
        showToast('Tính năng chỉ dành riêng cho Quản trị viên!', 'error');
        return;
      }
      showCrawlerModal.value = true;
    };

    const addCrawlerLog = (text, type = 'info') => {
      crawlerLogs.value.unshift({
        time: new Date().toLocaleTimeString(),
        text,
        type
      });
    };

    const startAutoCrawl = async () => {
      if (!isAdmin.value) return;
      isCrawling.value = true;
      crawlerProgress.value = 10;
      crawlerTab.value = 'logs';

      addCrawlerLog('Bắt đầu chu trình cào dữ liệu từ nguồn: ' + crawlerSource.value.toUpperCase() + '...', 'info');

      try {
        await new Promise(r => setTimeout(r, 600));
        crawlerProgress.value = 30;
        addCrawlerLog('Đang kết nối các group việc làm & mạng xã hội Tây Ninh...', 'info');

        await new Promise(r => setTimeout(r, 800));
        crawlerProgress.value = 60;
        const sourcePool = tayNinhCrawlDatabase[crawlerSource.value] || tayNinhCrawlDatabase.tuyendung;
        const countToTake = Math.min(crawlerCount.value, sourcePool.length);
        addCrawlerLog('Đã trích xuất và chuẩn hóa ' + countToTake + ' bài viết mới nhất.', 'info');

        await new Promise(r => setTimeout(r, 800));
        crawlerProgress.value = 85;
        addCrawlerLog('Đang đồng bộ hóa vào Cloud Firestore collection listings...', 'info');

        let insertedCount = 0;
        for (let i = 0; i < countToTake; i++) {
          const item = sourcePool[i];
          const uniqueSuffix = Date.now() + '_' + (i + 1);
          const newCard = {
            id: 'crawl_' + uniqueSuffix,
            title: item.title,
            subtitle: item.location,
            price: item.price,
            subprice: 'Vừa cào xong',
            location: item.location,
            district: item.district,
            category: crawlerSource.value,
            image: item.image,
            description: item.description,
            authorName: item.authorName || 'Hệ Thống Tổng Hợp Tây Ninh',
            authorEmail: 'admin.crawler@tayninhinfo.com',
            phone: item.phone || '0908.123.456',
            btnType: crawlerSource.value === 'tuyendung' ? 'apply' : 'call',
            badge: item.badge || 'Tin xác thực',
            likesCount: Math.floor(Math.random() * 20) + 5,
            likedByMe: false,
            viewsCount: Math.floor(Math.random() * 50) + 20,
            createdAt: new Date().toISOString(),
            comments: []
          };

          // Thêm vào mảng local
          cards.value.unshift(newCard);

          // Lưu vào Cloud Firestore
          if (db) {
            try {
              await addDoc(collection(db, 'listings'), newCard);
            } catch (e) {
              console.warn('Lỗi lưu Firestore crawler doc:', e);
            }
          }
          insertedCount++;
        }

        crawlerProgress.value = 100;
        addCrawlerLog('THÀNH CÔNG: Đã nạp ' + insertedCount + ' bài viết trực tiếp lên Cổng thông tin Tây Ninh TNHub!', 'success');
        showToast('Crawler thành công! Đã thêm ' + insertedCount + ' tin mới lên bảng tin.', 'success');
        playNotificationSound();
      } catch (err) {
        console.error('Crawler error:', err);
        addCrawlerLog('LỖI CRAWLER: ' + err.message, 'error');
        showToast('Lỗi khi cào dữ liệu: ' + err.message, 'error');
      } finally {
        isCrawling.value = false;
      }
    };

    const parseSocialPost = () => {
      const text = socialInputText.value.trim();
      if (!text) {
        showToast('Vui lòng nhập nội dung bài đăng mạng xã hội cần bóc tách!', 'warning');
        return;
      }

      // Trích xuất số điện thoại (10 chữ số)
      const phoneMatch = text.match(/(0\d{9,10}|\d{4}[.\s]\d{3}[.\s]\d{3})/);
      const phone = phoneMatch ? phoneMatch[0].replace(/[.\s]/g, '') : '0908.123.456';

      // Trích xuất mức giá hoặc mức lương
      let price = 'Thỏa thuận';
      const salaryMatch = text.match(/(\d+\s*-\s*\d+\s*(?:triệu|tr|tr\/tháng|triệu\/tháng)|\d+\s*(?:triệu|tỷ|tr|k))/i);
      if (salaryMatch) {
        price = salaryMatch[0];
      }

      // Trích xuất vị trí huyện thị tại Tây Ninh
      let location = 'TP. Tây Ninh';
      let district = 'tptayninh';
      const tLower = text.toLowerCase();
      if (tLower.includes('trảng bàng') || tLower.includes('trang bang')) {
        location = 'TX. Trảng Bàng, Tây Ninh';
        district = 'trangbang';
      } else if (tLower.includes('hòa thành') || tLower.includes('hoa thanh') || tLower.includes('long hoa')) {
        location = 'TX. Hòa Thành, Tây Ninh';
        district = 'hoathanh';
      } else if (tLower.includes('gò dầu') || tLower.includes('go dau') || tLower.includes('phước đông')) {
        location = 'Huyện Gò Dầu, Tây Ninh';
        district = 'godau';
      } else if (tLower.includes('dương minh châu') || tLower.includes('dầu tiếng')) {
        location = 'Huyện Dương Minh Châu, Tây Ninh';
        district = 'duongminhchau';
      } else if (tLower.includes('tân châu') || tLower.includes('tan chau')) {
        location = 'Huyện Tân Châu, Tây Ninh';
        district = 'tanchau';
      } else if (tLower.includes('tân biên') || tLower.includes('tan bien')) {
        location = 'Huyện Tân Biên, Tây Ninh';
        district = 'tanbien';
      } else if (tLower.includes('bến cầu') || tLower.includes('mộc bài')) {
        location = 'Huyện Bến Cầu, Tây Ninh';
        district = 'bencau';
      }

      // Xác định danh mục
      let category = 'raovat';
      let image = 'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=800&q=80';
      if (tLower.includes('tuyển') || tLower.includes('tìm việc') || tLower.includes('công nhân') || tLower.includes('lương')) {
        category = 'tuyendung';
        image = 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=800&q=80';
      } else if (tLower.includes('đất') || tLower.includes('nhà') || tLower.includes('bán đất') || tLower.includes('thổ cư') || tLower.includes('sổ hồng')) {
        category = 'batdongsan';
        image = 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=800&q=80';
      }

      // Trích xuất tiêu đề (câu đầu tiên)
      const firstLine = text.split(/\r?\n/)[0].replace(/[*#]/g, '').trim();
      const title = firstLine.length > 80 ? firstLine.substring(0, 80) + '...' : firstLine;

      parsedSocialCard.value = {
        title: title || 'Tin đăng bóc tách mạng xã hội Tây Ninh',
        price,
        location,
        district,
        phone,
        category,
        image,
        description: text
      };

      showToast('Đã bóc tách thông tin thành công!', 'success');
    };

    const saveParsedPost = async () => {
      if (!parsedSocialCard.value) return;
      const p = parsedSocialCard.value;
      const newCard = {
        id: 'social_' + Date.now(),
        title: p.title,
        subtitle: p.location,
        price: p.price,
        subprice: 'Vừa bóc tách MXH',
        location: p.location,
        district: p.district,
        category: p.category,
        image: p.image,
        description: p.description,
        authorName: 'Tin Bóc Tách MXH',
        authorEmail: 'crawler.social@tayninhinfo.com',
        phone: p.phone,
        btnType: p.category === 'tuyendung' ? 'apply' : 'call',
        badge: 'Bóc tách MXH',
        likesCount: 1,
        likedByMe: false,
        viewsCount: 5,
        createdAt: new Date().toISOString(),
        comments: []
      };

      cards.value.unshift(newCard);
      if (db) {
        try {
          await addDoc(collection(db, 'listings'), newCard);
        } catch(e) {
          console.warn('Lỗi lưu parsed social post:', e);
        }
      }

      showToast('Đã xuất bản tin bóc tách lên bảng tin TNHub!', 'success');
      parsedSocialCard.value = null;
      socialInputText.value = '';
      showCrawlerModal.value = false;
    };

    const openProfileModal = () => {
      if (!currentUser.value) {
        loginGoogle();
        return;
      }
      isViewingMyOwnProfile.value = true;
      userProfile.value.displayName = currentUser.value.displayName || '';
      userProfile.value.email = currentUser.value.email || '';
      userProfile.value.photoURL = currentUser.value.photoURL || '';

      // Đọc thêm từ localStorage nếu có
      try {
        const saved = localStorage.getItem('tnhub_user_profile_' + currentUser.value.uid);
        if (saved) {
          const parsed = JSON.parse(saved);
          userProfile.value = { ...userProfile.value, ...parsed };
        }
      } catch (e) {}

      showProfileModal.value = true;
    };

    const openUserProfile = async (target) => {
      if (!target) return;

      const targetEmail = target.authorEmail || target.email || '';
      const targetId = target.userId || target.authorId || target.uid || '';
      const isMe = currentUser.value && (
        (targetEmail && currentUser.value.email && targetEmail === currentUser.value.email) ||
        (targetId && currentUser.value.uid && targetId === currentUser.value.uid)
      );

      if (isMe) {
        openProfileModal();
        return;
      }

      // XEM PROFILE CỦA NGƯỜI KHÁC
      isViewingMyOwnProfile.value = false;
      const name = target.authorName || target.displayName || target.name || 'Thành viên Tây Ninh';
      const avatar = target.authorAvatar || target.photoURL || target.avatar || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=200&q=80';
      const location = target.location || 'Tây Ninh';

      // Danh sách bài đăng của người này
      const theirPosts = cards.value.filter(c => (targetEmail && c.authorEmail === targetEmail) || (targetId && c.userId === targetId));

      viewingUserProfile.value = {
        displayName: name,
        email: targetEmail || 'Chưa cập nhật',
        photoURL: avatar,
        coverURL: target.coverURL || 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1200&q=80',
        bio: target.bio || 'Thành viên cộng đồng Tây Ninh TNHub.',
        phone: target.phone || '',
        location: location,
        privacyMode: target.privacyMode || 'public',
        postsCount: theirPosts.length,
        posts: theirPosts,
        rawTarget: target
      };

      // Tải thông tin mới nhất từ Firestore users/{uid} nếu có
      if (db && targetId) {
        try {
          const userDocRef = doc(db, 'users', targetId);
          const userSnap = await getDoc(userDocRef);
          if (userSnap.exists()) {
            const udata = userSnap.data();
            if (udata.displayName) viewingUserProfile.value.displayName = udata.displayName;
            if (udata.photoURL) viewingUserProfile.value.photoURL = udata.photoURL;
            if (udata.coverURL) viewingUserProfile.value.coverURL = udata.coverURL;
            if (udata.bio) viewingUserProfile.value.bio = udata.bio;
            if (udata.phone) viewingUserProfile.value.phone = udata.phone;
            if (udata.location) viewingUserProfile.value.location = udata.location;
            if (udata.privacyMode) viewingUserProfile.value.privacyMode = udata.privacyMode;
          }
        } catch(err) {
          console.warn('Lỗi đọc profile từ Firestore:', err);
        }
      }

      showProfileModal.value = true;
    };

    const saveUserProfile = async () => {
      if (!currentUser.value) return;
      isSavingProfile.value = true;
      try {
        // Lưu vào localStorage
        localStorage.setItem('tnhub_user_profile_' + currentUser.value.uid, JSON.stringify(userProfile.value));

        // Cập nhật hiển thị currentUser
        if (userProfile.value.displayName) currentUser.value.displayName = userProfile.value.displayName;
        if (userProfile.value.photoURL) currentUser.value.photoURL = userProfile.value.photoURL;

        // Lưu vào Firestore collection 'users' nếu có db
        if (db) {
          try {
            const userRef = doc(db, 'users', currentUser.value.uid);
            await setDoc(userRef, {
              displayName: userProfile.value.displayName,
              email: userProfile.value.email,
              photoURL: userProfile.value.photoURL,
              coverURL: userProfile.value.coverURL,
              bio: userProfile.value.bio,
              phone: userProfile.value.phone,
              location: userProfile.value.location,
              privacyMode: userProfile.value.privacyMode || 'public',
              updatedAt: new Date().toISOString()
            }, { merge: true });
          } catch (err) {
            console.warn('Lưu Firestore users warning:', err);
          }
        }

        showToast('Đã lưu hồ sơ cá nhân và cài đặt quyền riêng tư thành công!', 'success');
        showProfileModal.value = false;
      } catch (e) {
        console.error('Lỗi khi lưu profile:', e);
        showToast('Lỗi khi lưu profile: ' + (e.message || ''), 'error');
      } finally {
        isSavingProfile.value = false;
      }
    };

    // BẠN BÈ FUNCTIONS
    const loadFriends = () => {
      try {
        const saved = localStorage.getItem('tnhub_friends');
        if (saved) {
          friendsList.value = JSON.parse(saved);
        }
      } catch (e) {}
    };

    const isFriend = (email) => {
      if (!email) return false;
      return friendsList.value.some(f => f.email === email);
    };

    const toggleFriend = (card) => {
      if (!currentUser.value) {
        loginGoogle();
        return;
      }
      const email = card.authorEmail || (card.id + '@tayninh.local');
      const name = card.authorName || 'Thành viên Tây Ninh';
      const avatar = card.authorAvatar || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80';
      const location = card.location || 'Tây Ninh';

      const idx = friendsList.value.findIndex(f => f.email === email);
      if (idx > -1) {
        friendsList.value.splice(idx, 1);
        showToast('Đã hủy kết bạn với ' + name, 'info');
      } else {
        friendsList.value.push({
          name,
          email,
          avatar,
          location,
          addedAt: new Date().toISOString()
        });
        showToast('Đã kết bạn thành công với ' + name + '! Bạn có thể nhắn tin riêng ngay.', 'success');
      }
      localStorage.setItem('tnhub_friends', JSON.stringify(friendsList.value));
    };

    const removeFriend = (email) => {
      friendsList.value = friendsList.value.filter(f => f.email !== email);
      localStorage.setItem('tnhub_friends', JSON.stringify(friendsList.value));
      showToast('Đã xóa khỏi danh sách bạn bè.', 'info');
    };

    // CHUẨN HÓA ĐỊNH DANH NGƯỜI DÙNG CHO CHAT 1-1 REALTIME
    const getUserChatKey = (obj) => {
      if (!obj) return '';
      if (typeof obj === 'string') {
        const s = obj.trim().toLowerCase();
        return s;
      }
      const email = obj.email || obj.authorEmail || obj.senderEmail || obj.receiverEmail || '';
      if (email && email.includes('@')) {
        return email.trim().toLowerCase();
      }
      const uid = obj.uid || obj.userId || obj.authorId || obj.senderId || obj.receiverId || obj.id || '';
      return uid.toString().trim().toLowerCase();
    };

    const getChatId = (userA, userB) => {
      const k1 = getUserChatKey(userA).replace(/[^a-zA-Z0-9]/g, '_');
      const k2 = getUserChatKey(userB).replace(/[^a-zA-Z0-9]/g, '_');
      if (!k1 || !k2) return 'general_chat';
      return [k1, k2].sort().join('___chat___');
    };

    const openPrivateChat = (target) => {
      if (!currentUser.value) {
        loginGoogle();
        return;
      }
      if (!target) return;

      // Hỗ trợ mọi loại target: card bài đăng, friend, user profile, notification
      const partnerEmail = (target.email || target.authorEmail || target.senderEmail || (target.rawTarget ? target.rawTarget.authorEmail : '') || '').toLowerCase().trim();
      const partnerName = target.name || target.displayName || target.authorName || target.senderName || 'Thành viên Tây Ninh';
      const partnerAvatar = target.avatar || target.photoURL || target.authorAvatar || target.senderAvatar || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=80&q=80';
      const partnerId = partnerEmail || target.userId || target.uid || (target.id ? ('user_' + target.id) : 'partner');

      const myEmail = (currentUser.value.email || '').toLowerCase().trim();
      if (myEmail && partnerEmail && myEmail === partnerEmail) {
        showToast('Đây là bài viết hoặc tài khoản của chính bạn. Không thể tự chat với mình!', 'info');
        return;
      }

      activeChatPartner.value = {
        id: partnerId,
        name: partnerName,
        email: partnerEmail,
        avatar: partnerAvatar
      };

      const chatId = getChatId(currentUser.value, activeChatPartner.value);

      privateMessages.value = [];
      showPrivateChat.value = true;
      if (showFriendsModal.value) showFriendsModal.value = false;
      if (showNotificationDropdown.value) showNotificationDropdown.value = false;

      // Hủy listener cũ nếu có
      if (privateChatUnsubscribe) {
        privateChatUnsubscribe();
        privateChatUnsubscribe = null;
      }

      // Lắng nghe Firestore realtime cho private chat
      if (db) {
        try {
          const msgsRef = collection(db, 'private_chats', chatId, 'messages');
          const q = query(msgsRef, orderBy('createdAt', 'asc'), limit(100));
          privateChatUnsubscribe = onSnapshot(q, (snapshot) => {
            const list = [];
            snapshot.forEach(d => {
              const data = d.data();
              const isMe = (myEmail && data.senderEmail && data.senderEmail.toLowerCase() === myEmail) ||
                           (currentUser.value.uid && data.senderId === currentUser.value.uid);
              list.push({
                id: d.id,
                ...data,
                isMe: isMe
              });
            });
            privateMessages.value = list;

            // Cuộn xuống tin nhắn mới nhất
            setTimeout(() => {
              const box = document.getElementById('privateChatBox');
              if (box) box.scrollTop = box.scrollHeight;
            }, 80);
          }, (err) => {
            console.warn('Private chat snapshot warning:', err);
          });
        } catch (err) {
          console.warn('Private chat setup error:', err);
        }
      }
    };

    const sendPrivateMessage = async () => {
      const text = privateMessageInput.value.trim();
      if (!text || !activeChatPartner.value || !currentUser.value) return;

      const myEmail = (currentUser.value.email || '').toLowerCase().trim();
      const partnerEmail = (activeChatPartner.value.email || '').toLowerCase().trim();
      const chatId = getChatId(currentUser.value, activeChatPartner.value);

      const newMsg = {
        chatId: chatId,
        senderId: currentUser.value.uid || '',
        senderName: currentUser.value.displayName || 'Thành viên Tây Ninh',
        senderEmail: myEmail,
        senderAvatar: currentUser.value.photoURL || '',
        receiverId: activeChatPartner.value.id,
        receiverEmail: partnerEmail,
        receiverName: activeChatPartner.value.name,
        text: text,
        createdAt: new Date().toISOString()
      };

      // Optimistic local update
      privateMessages.value.push({
        id: 'temp_' + Date.now(),
        ...newMsg,
        isMe: true
      });

      privateMessageInput.value = '';
      playNotificationSound();

      setTimeout(() => {
        const box = document.getElementById('privateChatBox');
        if (box) box.scrollTop = box.scrollHeight;
      }, 50);

      if (db) {
        try {
          // 1. Lưu vào collection tin nhắn riêng
          await addDoc(collection(db, 'private_chats', chatId, 'messages'), newMsg);

          // 2. Tạo realtime notification cho receiver
          if (partnerEmail && partnerEmail !== myEmail) {
            await addDoc(collection(db, 'notifications'), {
              type: 'private_chat',
              title: 'Tin nhắn từ ' + (currentUser.value.displayName || 'Thành viên'),
              content: text,
              senderName: currentUser.value.displayName || 'Thành viên Tây Ninh',
              senderEmail: myEmail,
              senderAvatar: currentUser.value.photoURL || '',
              receiverEmail: partnerEmail,
              chatId: chatId,
              read: false,
              createdAt: new Date().toISOString()
            });
          }
        } catch (e) {
          console.warn('Lỗi gửi private message:', e);
          showToast('Lỗi gửi tin nhắn: ' + (e.message || 'Vui lòng thử lại'), 'error');
        }
      }
    };

    const closePrivateChat = () => {
      if (privateChatUnsubscribe) {
        privateChatUnsubscribe();
        privateChatUnsubscribe = null;
      }
      showPrivateChat.value = false;
      activeChatPartner.value = null;
    };

    // Khởi tạo tải bạn bè khi component mount
    loadFriends();

    onMounted(() => {
      if (auth) {
        onAuthStateChanged(auth, (user) => {
          if (user) {
            currentUser.value = {
              uid: user.uid,
              displayName: user.displayName,
              email: user.email,
              photoURL: user.photoURL
            };
            // Kích hoạt lắng nghe Realtime Notifications cho người dùng này
            listenRealtimeNotifications(user.email);
          } else {
            currentUser.value = null;
            if (notifUnsubscribe) {
              notifUnsubscribe();
              notifUnsubscribe = null;
            }
            notifications.value = [];
            unreadNotificationCount.value = 0;
          }
        });
      }

      // LẮNG NGHE REALTIME COLLECTION 'listings' TỪ FIREBASE (100% CLOUD FIRESTORE)
      if (db) {
        try {
          const listingsRef = collection(db, 'listings');
          onSnapshot(listingsRef, (snapshot) => {
            if (!snapshot.empty) {
              // Lưu giữ trạng thái UI hiện tại của từng thẻ (không tự ý đóng khung comment, giữ like, giữ text đang gõ)
              const stateMap = {};
              cards.value.forEach(c => {
                if (c && c.id) {
                  stateMap[c.id] = {
                    showComments: c.showComments,
                    likedByMe: c.likedByMe,
                    newCommentText: c.newCommentText
                  };
                }
              });

              const liveList = [];
              snapshot.forEach((d) => {
                const rawData = { id: d.id, ...d.data() };
                const enriched = enrichListingWithFirebaseDoc(rawData);
                // Phục hồi trạng thái UI của thẻ
                if (stateMap[d.id]) {
                  if (stateMap[d.id].showComments !== undefined) enriched.showComments = stateMap[d.id].showComments;
                  if (stateMap[d.id].likedByMe !== undefined) enriched.likedByMe = stateMap[d.id].likedByMe;
                  if (stateMap[d.id].newCommentText) enriched.newCommentText = stateMap[d.id].newCommentText;
                }
                liveList.push(enriched);
              });
              liveList.sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
              cards.value = liveList;



    // ĐỒNG BỘ REALTIME VÀO MODAL CHI TIẾT NẾU ĐANG MỞ (Không làm tắt modal)
              if (selectedDetailCard.value && selectedDetailCard.value.id) {
                const matched = liveList.find(c => c.id === selectedDetailCard.value.id);
                if (matched) {
                  selectedDetailCard.value.comments = matched.comments;
                  selectedDetailCard.value.likesCount = matched.likesCount;
                  selectedDetailCard.value.viewsCount = matched.viewsCount;
                  if (matched.likedByMe !== undefined) selectedDetailCard.value.likedByMe = matched.likedByMe;
                }
              }

              // ĐỒNG BỘ REALTIME VÀO DIALOG BÌNH LUẬN NẾU ĐANG MỞ
              if (activeCommentCard.value && activeCommentCard.value.id) {
                const matchedCommentCard = liveList.find(c => c.id === activeCommentCard.value.id);
                if (matchedCommentCard) {
                  activeCommentCard.value.comments = matchedCommentCard.comments;
                  activeCommentCard.value.likesCount = matchedCommentCard.likesCount;
                  activeCommentCard.value.viewsCount = matchedCommentCard.viewsCount;
                  if (matchedCommentCard.likedByMe !== undefined) activeCommentCard.value.likedByMe = matchedCommentCard.likedByMe;
                }
              }

              isFirebaseConnected.value = true;
              isDataLoading.value = false;
              console.log('Đã đồng bộ ' + liveList.length + ' tin đăng realtime từ Cloud Firestore');
            } else {
              isDataLoading.value = false;
            }
          }, (err) => {
            console.warn('Firestore snapshot error:', err);
            isDataLoading.value = false;
          });
        } catch (err) {
          console.warn('Firestore setup error:', err);
          isDataLoading.value = false;
        }

        // LẮNG NGHE REALTIME COLLECTION 'messages' VÀ PHÁT NOTIFICATION
        try {
          const messagesRef = collection(db, 'messages');
          let initialMessagesDone = false;
          onSnapshot(messagesRef, (snapshot) => {
            const liveMsgs = [];
            snapshot.forEach(d => liveMsgs.push({ id: d.id, ...d.data() }));
            liveMsgs.sort((a, b) => (b.createdAt || '').localeCompare(a.createdAt || ''));
            if (liveMsgs.length > 0) {
              communityMessages.value = liveMsgs;
            }

            if (initialMessagesDone) {
              snapshot.docChanges().forEach(change => {
                if (change.type === 'added') {
                  const data = change.doc.data();
                  unreadMessageCount.value++;
                  playNotificationSound();
                  showToast('[Tin nhắn mới] ' + (data.senderName || 'Cộng đồng') + ': "' + (data.text ? data.text.substring(0, 45) : '') + '..."', 'success', 'Tin Nhắn Realtime');
                }
              });
            }
            initialMessagesDone = true;
          }, (err) => {
            if (err && err.code === 'permission-denied') {
              console.info('Firestore: Chưa mở quyền đọc cho collection messages trong Rules (có thể bổ sung sau).');
            } else {
              console.warn('Messages snapshot warning:', err);
            }
          });
        } catch (err) {
          console.warn('Messages setup error:', err);
        }
      }

      // Tự động tải kết quả xổ số kiến thiết mới nhất
      fetchLotteryData();
      // Tự động cập nhật danh sách video nói về tỉnh Tây Ninh
      fetchTayNinhVideos();
    });

    return {
      displayLimit,
      activeDistrict,
      activePriceRange,
      sortAsc,
